using System;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Check which projects failed
System.Console.WriteLine("=== FAILED TARGETS ===");
build.VisitAllChildren<Target>(target =>
{
    if (!target.IsLowRelevance && target.Name == "Build")
    {
        var proj = target.GetNearestParent<Project>();
        System.Console.WriteLine($"  {proj?.Name}: Build target found");
    }
});

// Look for MSB3202 or similar cascading errors
System.Console.WriteLine("\n=== ALL DIAGNOSTICS (Error nodes) ===");
build.VisitAllChildren<AbstractDiagnostic>(diag =>
{
    var proj = diag.GetNearestParent<Project>();
    System.Console.WriteLine($"[{diag.GetType().Name}] {proj?.Name ?? "?"} | {diag.Code} | {diag.File}:{diag.LineNumber} | {diag.Text}");
});

// Check Api build - did it fail because Services failed?
System.Console.WriteLine("\n=== MSBuild task errors (project reference failures) ===");
build.VisitAllChildren<Message>(msg =>
{
    if (msg.Text != null && (msg.Text.Contains("previously failed") || msg.Text.Contains("not build") || msg.Text.Contains("dependency")))
        System.Console.WriteLine($"  {msg.Text}");
});
