using System;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Check all projects and their build result
System.Console.WriteLine("=== PROJECT EVALUATIONS & RESULTS ===");
build.VisitAllChildren<Project>(project =>
{
    bool hasErrors = false;
    project.VisitAllChildren<Error>(e => hasErrors = true);
    System.Console.WriteLine($"  {project.Name} (eval #{project.EvaluationId}) hasErrors={hasErrors}");
});

// Check for the Api project specifically - did it even attempt to compile?
System.Console.WriteLine("\n=== CSC TASKS (compilation attempts) ===");
build.VisitAllChildren<Task>(task =>
{
    if (task.Name == "Csc")
    {
        var proj = task.GetNearestParent<Project>();
        System.Console.WriteLine($"  Csc in {proj?.Name}");
    }
});

// Get source file content from Csc task parameters
System.Console.WriteLine("\n=== SOURCE FILES IN CSC COMMANDS ===");
build.VisitAllChildren<Task>(task =>
{
    if (task.Name == "Csc")
    {
        var proj = task.GetNearestParent<Project>();
        task.VisitAllChildren<Parameter>(param =>
        {
            if (param.Name == "Sources")
            {
                System.Console.WriteLine($"  {proj?.Name} sources:");
                param.VisitAllChildren<Item>(item =>
                {
                    System.Console.WriteLine($"    {item.Text}");
                });
            }
        });
    }
});
